- return regexp.MustCompile(`\\d+`).FindString(s)
+ n, err := strconv.ParseInt(s, 10, 64)
+ if err != nil {
+   return 0, fmt.Errorf("parsing %q: %w", s, err)
+ }
+ return n, nil

+ func dedupe(items []string) []string {
+   var out []string
+   for _, x := range items {
+     found := false
+     for _, y := range out {
+       if x == y { found = true; break }
+     }
+     if !found { out = append(out, x) }
+   }
+   return out
+ }
